// app/dashboard/team/page.tsx
import { getTeam, getMemberQuota } from '~/lib/data/team';
import { getBillingStatus } from '~/lib/data/billing';

export default async function TeamPage() {
  const team = await getTeam();
  const billing = await getBillingStatus(); // independent of team
  return (
    <>
      <BillingBanner status={billing} />
      <ul>
        {team.members.map((m) => (
          <MemberRow key={m.id} member={m} />
        ))}
      </ul>
    </>
  );
}

async function MemberRow({ member }: { member: Member }) {
  const quota = await getMemberQuota(member.id);
  return (
    <li>
      {member.name} — {quota.used}/{quota.limit}
    </li>
  );
}

// lib/data/team.ts (added)
import { db } from '~/lib/db';
export async function getMemberQuota(memberId: string) {
  return db.query.quotas.findFirst({ where: (q, { eq }) => eq(q.memberId, memberId) });
}
